param([string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName System.Runtime.Serialization
function Assert([bool]$condition,[string]$message){if(-not$condition){throw $message}}
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$parametersType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolParameterData',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s56-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function Field([string]$name){$value=$mainType.GetField($name,$all).GetValue($window);Write-Output -NoEnumerate $value}
function Kind([string]$name){[Enum]::Parse($kindType,$name)}
function Tool([string]$kind,[string]$name){$mainType.GetMethod('CreateFlowTool',$private).Invoke($window,[object[]]@((Kind $kind),$name,$true,$null))}
function Out($tool,[string]$name){$args=[object[]]@($name,$null);Assert($tool.GetType().GetMethod('TryGetOutputValue').Invoke($tool,$args))('Missing output '+$name);$args[1]}
function Run($tool){$mainType.GetMethod('ExecuteFlowTool',$private).Invoke($window,[object[]]@($tool,'S56 smoke'))}
function RunFailure($tool){try{Run $tool|Out-Null;throw 'Expected execution failure'}catch{if($_.Exception.InnerException){return $_.Exception.InnerException.Message};return $_.Exception.Message}}
function LoadDock($tool){$mainType.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($tool.PSObject.BaseObject))|Out-Null}
function Near([double]$actual,[double]$expected){[Math]::Abs($actual-$expected)-lt0.0000001}
try{
  Assert((Field 'DeveloperAppBar').Height-eq32) 'Developer application bar is not compact';Assert((Field 'DeveloperToolbarPanel').GetType().Name-eq'StackPanel') 'High-frequency command row can still wrap';Assert((Field 'DeveloperMetricStrip').Children.Count-eq4) 'Compact metric strip is incomplete';Assert((Field 'DeveloperMorePopup').GetType().Name-eq'Popup') 'Low-frequency commands still consume permanent layout space'
  foreach($name in @('SaveRecipeButton','OpenImageButton','RunOnceButton','StopRunButton','EnterProductionModeButton')){Assert((Field $name).MinHeight-le26)($name+' remains oversized')}
  $setMode=$mainType.GetMethod('SetProductionRunMode',$private);$setMode.Invoke($window,[object[]]@($true))|Out-Null;Assert((Field 'ProductionToolbarPanel').Visibility.ToString()-eq'Visible'-and(Field 'DeveloperToolbarPanel').Visibility.ToString()-eq'Collapsed') 'Production mode command strip failed';$setMode.Invoke($window,[object[]]@($false))|Out-Null;Assert((Field 'DeveloperToolbarPanel').Visibility.ToString()-eq'Visible'-and(Field 'ProductionToolbarPanel').Visibility.ToString()-eq'Collapsed') 'Developer mode command strip was not restored'

  $flow=Field 'flowTools';$source=Tool ImageSource 'Numeric Inputs';$parser=Tool TextParser 'Parsed A';$calculation=Tool NumericCalculation 'Numeric Calculation';$judge=Tool NumericJudge 'Calculation Judge';$text=Tool TextAssembly 'Calculation Text';$tcp=Tool TcpClientExchange 'Calculation TCP';foreach($tool in @($source,$parser,$calculation,$judge,$text,$tcp)){$flow.Add($tool)}
  $source.SetOutputValue('SN','12.5');$source.SetOutputValue('Width',[double]2.5);$source.SetOutputValue('ResultCode','OK');$source.ResultCode='OK';$parser.SetInputBinding('String',$source.ToolId,'SN');$parser.Parameters.TextParserMode='Literal';$parser.Parameters.TextParserPattern=',';$parser.Parameters.TextParserFieldIndex=1;$parser.Parameters.TextParserConvertNumber=$true;Assert((Run $parser).ResultCode-eq'OK') 'Text Parser source failed'
  $calculation.SetInputBinding('NumberA',$parser.ToolId,'Number');$calculation.SetInputBinding('NumberB',$source.ToolId,'Width');$inputs=$metadataType.GetMethod('GetInputPorts',[Reflection.BindingFlags]'Static,Public').Invoke($null,[object[]]@((Kind NumericCalculation)));$outputs=$metadataType.GetMethod('GetOutputPorts',[Reflection.BindingFlags]'Static,Public').Invoke($null,[object[]]@((Kind NumericCalculation)));Assert($inputs.Count-eq2-and-not$inputs[0].IsOptional-and$inputs[1].IsOptional) 'Numeric Calculation input contract failed';Assert(($outputs|Where-Object PortName -eq 'Number').DataType-eq'Number'-and($outputs|Where-Object PortName -eq 'Operation').DataType-eq'String') 'Numeric Calculation output contract failed'
  $cases=@(@('Add',15.0),@('Subtract',10.0),@('Multiply',31.25),@('Divide',5.0),@('Minimum',2.5),@('Maximum',12.5));foreach($case in $cases){$calculation.Parameters.NumericCalculationOperation=$case[0];$record=Run $calculation;Assert($record.ResultCode-eq'OK'-and(Near ([double](Out $calculation Number)) ([double]$case[1])))('Operation failed: '+$case[0]);Assert([int](Out $calculation OperandCount)-eq2)('Operand count failed: '+$case[0])}
  $source.SetOutputValue('SN','-3.25');Assert((Run $parser).ResultCode-eq'OK') 'Negative parser source failed';$calculation.Parameters.NumericCalculationOperation='Absolute';Assert((Run $calculation).ResultCode-eq'OK'-and(Near ([double](Out $calculation Number)) 3.25)-and[int](Out $calculation OperandCount)-eq1) 'Absolute operation failed'
  $source.SetOutputValue('SN','2.675');Run $parser|Out-Null;$calculation.Parameters.NumericCalculationOperation='Round';$calculation.Parameters.NumericCalculationRoundDigits=2;Assert((Run $calculation).ResultCode-eq'OK'-and(Near ([double](Out $calculation Number)) 2.68)) 'Away-from-zero rounding failed'

  $judge.SetInputBinding('Value',$calculation.ToolId,'Number');$judge.InputToolId=$calculation.ToolId;$judge.InputPortName='Number';$judge.NumericLowerLimit=2.67;$judge.NumericUpperLimit=2.69;Assert((Run $judge).ResultCode-eq'OK') 'Numeric Calculation Number did not drive Numeric Judge';$text.SetInputBinding('Number',$calculation.ToolId,'Number');$text.Parameters.TextAssemblyTemplate='VALUE={Number}';Assert((Run $text).ResultCode-eq'OK'-and(Out $text Text)-eq'VALUE=2.68') 'Numeric Calculation Number did not drive Text Assembly';$tcp.SetInputBinding('Number',$calculation.ToolId,'Number');Assert($tcp.GetInputBinding('Number').SourceToolId-eq$calculation.ToolId) 'Numeric Calculation Number did not bind to TCP'

  $calculation.Parameters.NumericCalculationOperation='Divide';$source.SetOutputValue('Width',[double]0);Assert((RunFailure $calculation)-match'不能为零'-and$calculation.ResultCode-eq'NG') 'Zero division was not rejected';$calculation.RemoveInputBinding('NumberB');$calculation.Parameters.NumericCalculationOperation='Add';Assert((RunFailure $calculation)-match'NumberB'-and$calculation.ResultCode-eq'NG') 'Missing NumberB was not rejected'
  $calculation.SetInputBinding('NumberB',$source.ToolId,'Width');$source.SetOutputValue('Width',[double]::NaN);Assert((RunFailure $calculation)-match'有限数值'-and$calculation.ResultCode-eq'NG') 'NaN input was not rejected';$source.SetOutputValue('Width',[double]::PositiveInfinity);Assert((RunFailure $calculation)-match'有限数值'-and$calculation.ResultCode-eq'NG') 'Infinity input was not rejected'
  $calculation.Parameters.NumericCalculationOperation='Round';$calculation.Parameters.NumericCalculationRoundDigits=16;Assert(([string]$calculation.Parameters.Validate((Kind NumericCalculation))).Length-gt0) 'Invalid precision was not rejected';$calculation.Parameters.NumericCalculationRoundDigits=2

  $serializer=[System.Runtime.Serialization.Json.DataContractJsonSerializer]::new($parametersType);$bytes=[Text.Encoding]::UTF8.GetBytes('{}');$stream=New-Object IO.MemoryStream(,$bytes);try{$old=$serializer.ReadObject($stream)}finally{$stream.Dispose()};$old.Normalize();Assert($old.NumericCalculationOperation-eq'Add'-and$old.NumericCalculationRoundDigits-eq0) 'Old recipe Numeric Calculation defaults failed'
  LoadDock $calculation;Assert((Field 'DockNumericCalculationPanel').Visibility.ToString()-eq'Visible') 'Numeric Calculation dock panel is missing';Assert((Field 'DockNumericCalculationOperationComboBox').Visibility.ToString()-eq'Visible') 'Numeric Calculation key operation is hidden';$advanced=Field 'dockAdvancedParameterRows';Assert($advanced.Count-eq1-and$advanced[0].Row.Height.Value-eq0) 'Numeric Calculation advanced precision is not collapsed'
  (Field 'DockNumericCalculationOperationComboBox').SelectedValue='Maximum';(Field 'DockNumericCalculationRoundDigitsTextBox').Text='3';$oldOperation=$calculation.Parameters.NumericCalculationOperation;$apply=$mainType.GetMethod('ApplyDockConfigurationDraft',$private);Assert([bool]$apply.Invoke($window,[object[]]@($true))) 'Numeric Calculation dock Apply failed';Assert($calculation.Parameters.NumericCalculationOperation-eq'Maximum'-and$calculation.Parameters.NumericCalculationRoundDigits-eq3) 'Numeric Calculation draft was not stored'
  $mainType.GetMethod('UndoFlowEditButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$restored=$flow|Where-Object ToolId -eq $calculation.ToolId|Select-Object -First 1;Assert($restored.Parameters.NumericCalculationOperation-eq$oldOperation) 'Numeric Calculation undo failed';$mainType.GetMethod('RedoFlowEditButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$restored=$flow|Where-Object ToolId -eq $calculation.ToolId|Select-Object -First 1;Assert($restored.Parameters.NumericCalculationOperation-eq'Maximum') 'Numeric Calculation redo failed'
  LoadDock $restored;$list=Field 'FlowToolList';$list.SelectedItems.Clear();$list.SelectedItem=$restored;$before=$flow.Count;$mainType.GetMethod('DuplicateFlowToolButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$copy=$flow|Where-Object{$_.Kind.ToString()-eq'NumericCalculation'-and$_.ToolId-ne$restored.ToolId}|Select-Object -Last 1;Assert($flow.Count-eq($before+1)-and$copy.Parameters.NumericCalculationOperation-eq'Maximum') 'Numeric Calculation copy failed';$recipe=$mainType.GetMethod('CaptureRecipe',$private).Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object ToolId -eq $restored.ToolId|Select-Object -First 1;Assert($saved.Parameters.NumericCalculationOperation-eq'Maximum'-and$saved.Parameters.NumericCalculationRoundDigits-eq3) 'Numeric Calculation recipe persistence failed'
  Write-Output 'S56 compact application bar and Numeric Calculation operations/downstream/recipe lifecycle passed'
}finally{$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
